fun stamp =>
  (have leapYearEpoch := 11017;
    have daysPer400Y := 365 * 400 + 97;
    have daysPer100Y := 365 * 100 + 24;
    have daysPer4Y := 365 * 4 + 1;
    let nanos := stamp.toNanoseconds;
    have secs := nanos.toSeconds;
    let remNano :=
      Std.Time.Internal.Bounded.LE.byMod nanos.val 1000000000
        Std.Time.PlainDateTime.ofWallTime._proof_1✝;
    match
      if h : ↑remNano < 0 then
        (((remNano.truncateTop ⋯).add 1000000000).expandBottom
            Std.Time.PlainDateTime.ofWallTime._proof_3✝,
          secs - 1)
      else (remNano.truncateBottom ⋯, secs) with
    | (remNano, secs) =>
      have daysSinceEpoch := secs.toDays;
      have boundedDaysSinceEpoch := daysSinceEpoch;
      have rawDays := boundedDaysSinceEpoch - leapYearEpoch;
      let rem :=
        Std.Time.Internal.Bounded.LE.byMod secs.val 86400
          Std.Time.PlainDateTime.ofWallTime._proof_7✝;
      match
        if h : ↑rem ≤ -1 then
          have remSecs := rem.truncateTop h;
          have remSecs := remSecs.add 86400;
          have rawDays := rawDays - 1;
          (remSecs.expandBottom Std.Time.PlainDateTime.ofWallTime._proof_8✝, rawDays)
        else
          have h := rem.truncateBottom ⋯;
          (h, rawDays) with
      | (remSecs, days) =>
        have quadracentennialCycles := days.val / daysPer400Y;
        have remDays := days.val % daysPer400Y;
        have __do_jp := fun __r quadracentennialCycles remDays =>
          have centenialCycles := remDays / daysPer100Y;
          have __do_jp := fun __r centenialCycles =>
            have remDays := remDays - centenialCycles * daysPer100Y;
            have quadrennialCycles := remDays / daysPer4Y;
            have __do_jp := fun __r quadrennialCycles =>
              have remDays := remDays - quadrennialCycles * daysPer4Y;
              have remYears := remDays / 365;
              have __do_jp := fun __r remYears =>
                have remDays := remDays - remYears * 365;
                have year :=
                  2000 + remYears + 4 * quadrennialCycles + 100 * centenialCycles +
                    400 * quadracentennialCycles;
                have months := [31, 30, 31, 30, 31, 31, 30, 31, 30, 31, 31, 29];
                have mon := 0;
                do
                let __s ←
                  forIn months (remDays, mon) fun monLen __s =>
                      have remDays := __s.1;
                      have mon := __s.2;
                      have mon := mon + 1;
                      if remDays < monLen then pure (ForInStep.done (remDays, mon))
                      else
                        have remDays := remDays - monLen;
                        pure (ForInStep.yield (remDays, mon))
                have remDays : ℤ := __s.1
                let mon : Fin 13 := __s.2
                have mday : Fin 31 := Fin.ofNat 31 remDays.toNat
                have __do_jp : Std.Time.Month.Ordinal → ℤ → Id Std.Time.PlainDateTime :=
                  fun hmon year =>
                  have second := remSecs.emod 60 Std.Time.PlainDateTime.ofWallTime._proof_12✝;
                  have minute :=
                    (remSecs.ediv 60 Std.Time.PlainDateTime.ofWallTime._proof_13✝).emod 60
                      Std.Time.PlainDateTime.ofWallTime._proof_12✝;
                  have hour := remSecs.ediv 3600 Std.Time.PlainDateTime.ofWallTime._proof_14✝;
                  have nano :=
                    Std.Time.Internal.Bounded.LE.byEmod nanos.val 1000000000
                      Std.Time.PlainDateTime.ofWallTime._proof_15✝;
                  pure
                    {
                      date :=
                        Std.Time.PlainDate.ofYearMonthDayClip year hmon
                          (Std.Time.Day.Ordinal.ofFin mday.succ),
                      time :=
                        Std.Time.PlainTime.ofHourMinuteSecondsNano
                          (hour.expandTop Std.Time.PlainDateTime.ofWallTime._proof_16✝) minute
                          (second.expandTop Std.Time.PlainDateTime.ofWallTime._proof_17✝) nano }
                if h₁ : ↑mon > 10 then
                    have year := year + 1;
                    do
                    let hmon ← pure (Std.Time.Month.Ordinal.ofNat (↑mon - 10) ⋯)
                    __do_jp hmon year
                  else do
                    let hmon ← pure (Std.Time.Month.Ordinal.ofNat (↑mon + 2) ⋯)
                    __do_jp hmon year;
              if remYears = 4 then
                have remYears := remYears - 1;
                __do_jp () remYears
              else __do_jp () remYears;
            if quadrennialCycles = 25 then
              have quadrennialCycles := quadrennialCycles - 1;
              __do_jp () quadrennialCycles
            else __do_jp () quadrennialCycles;
          if centenialCycles = 4 then
            have centenialCycles := centenialCycles - 1;
            __do_jp () centenialCycles
          else __do_jp () centenialCycles;
        if remDays < 0 then
          have remDays := remDays + daysPer400Y;
          have quadracentennialCycles := quadracentennialCycles - 1;
          __do_jp () quadracentennialCycles remDays
        else __do_jp () quadracentennialCycles remDays).run

