fun builder aw =>
  have offset :=
    (Std.Time.GenericFormat.DateBuilder.O✝ builder <|>
          Std.Time.GenericFormat.DateBuilder.X✝ builder <|>
            Std.Time.GenericFormat.DateBuilder.x✝ builder <|>
              Std.Time.GenericFormat.DateBuilder.Z✝ builder).getD
      Std.Time.TimeZone.Offset.zero;
  have tz :=
    { offset := offset,
      name :=
        (Std.Time.GenericFormat.DateBuilder.V✝ builder <|>
              Std.Time.GenericFormat.DateBuilder.z✝ builder).getD
          (offset.toIsoString true),
      abbreviation :=
        (Std.Time.GenericFormat.DateBuilder.zabbrev✝ builder).getD (offset.toIsoString true),
      isDST := false };
  have month := (Std.Time.GenericFormat.DateBuilder.MorL✝ builder).getD 0;
  have day := (Std.Time.GenericFormat.DateBuilder.d✝ builder).getD 0;
  have era := (Std.Time.GenericFormat.DateBuilder.G✝ builder).getD Std.Time.Year.Era.ce;
  have year :=
    (Std.Time.GenericFormat.DateBuilder.u✝ builder <|>
          (fun x => Std.Time.GenericFormat.DateBuilder.convertYearAndEra✝ x era) <$>
              Std.Time.GenericFormat.DateBuilder.y✝ builder <|>
            Std.Time.GenericFormat.DateBuilder.Y✝ builder).getD
      0;
  have hour :=
    match Std.Time.GenericFormat.DateBuilder.a✝ builder with
    | some marker =>
      marker.toAbsolute <$> Std.Time.GenericFormat.DateBuilder.h✝ builder <|>
        marker.toAbsolute <$> (fun x => x.add 1) <$> Std.Time.GenericFormat.DateBuilder.K✝ builder
    | x => none;
  have hour :=
    (hour <|>
          have one := Std.Time.GenericFormat.DateBuilder.H✝ builder;
          have other := (fun x => x.sub 1) <$> Std.Time.GenericFormat.DateBuilder.k✝ builder;
          one <|> other).getD
      ⟨0, Std.Time.GenericFormat.DateBuilder.build._proof_1✝⟩;
  have minute := (Std.Time.GenericFormat.DateBuilder.m✝ builder).getD 0;
  have second := (Std.Time.GenericFormat.DateBuilder.s✝ builder).getD 0;
  have nano :=
    (Std.Time.GenericFormat.DateBuilder.n✝ builder <|>
          Std.Time.GenericFormat.DateBuilder.S✝ builder).getD
      0;
  have time :=
    (Std.Time.PlainTime.ofNanoseconds <$> Std.Time.GenericFormat.DateBuilder.N✝ builder <|>
          Std.Time.PlainTime.ofMilliseconds <$> Std.Time.GenericFormat.DateBuilder.A✝ builder).getD
      { hour := hour, minute := minute, second := second, nanosecond := nano };
  have datetime :=
    if valid : year.Valid month day then
      have date := { year := year, month := month, day := day, valid := valid };
      some { date := date, time := time }
    else none;
  have zoneTz :=
    match aw with
    | Std.Time.Awareness.only newTz => newTz
    | Std.Time.Awareness.any => tz;
  (fun x => Std.Time.DateTime.ofPlainDateTime x (Std.Time.TimeZone.ZoneRules.ofTimeZone zoneTz)) <$>
    datetime

fun offset withMinutes withSeconds colon =>
  match if offset.second.val ≥ 0 then ("+", offset.second) else ("-", -offset.second) with
  | (sign, time) =>
    have time := Std.Time.PlainTime.ofSeconds time;
    have pad := Std.Time.leftPadAscii✝ 2 '0' ∘ toString;
    have data := toString sign ++ toString (pad ↑time.hour);
    have data :=
      if withMinutes = true then
        toString data ++ toString (if colon = true then ":" else "") ++ toString (pad ↑time.minute)
      else data;
    have data :=
      if withSeconds = true ∧ ↑time.second ≠ 0 then
        toString data ++ toString (if colon = true then ":" else "") ++ toString (pad ↑time.second)
      else data;
    data

